#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
# Compare whole syncs of one machine from the CSVs in data/sync/<machine>/ (standard library only).
# Rules:
# - Stall: a gap of 600 s or more between two consecutive recorded blocks across which the node process changed: the
#   last process sample before the gap and the first after it have different pids (it had to be restarted to move again). Slow, disk-bound stretches are sync time, not stalls.
# - Catch-up: the first height h from which the run receives blocks within LAG s of their header timestamp, checked at
#   h and every 10th block of the next 200 (at least 10 present). Found by binary search.
# - Common range: from the first block after START_HEIGHT to the earliest catch-up block of all runs.
# Usage: python3 -I sync_compare.py data/sync/<machine> [data/sync/block_timestamps.csv.gz]
import csv, gzip, os, sys
START_HEIGHT, LAG, STALL_GAP, MIB = 3102000, 1800, 600, 2 ** 20
d = sys.argv[1]
tsf = sys.argv[2] if len(sys.argv) > 2 else os.path.join(os.path.dirname(d.rstrip('/')), 'block_timestamps.csv.gz')
def rows(p):
    with gzip.open(p, 'rt') as f: return list(csv.DictReader(f))
stamp = {int(r['height']): int(r['timestamp_utc_epoch']) for r in rows(tsf)}
runs = []
with open(os.path.join(d, 'runs.csv')) as f:
    for line in f:
        name, a, b = line.strip().split(','); runs.append((name, float(a)))
def fmt(s): s = int(round(s)); return f"{s // 3600} h {s % 3600 // 60:02d} min"
R = {}
for name, start in runs:
    blk = {int(r['height']): float(r['added_utc_epoch']) for r in rows(os.path.join(d, f'blocks_{name}.csv.gz'))}
    pi = [(float(r['time_utc_epoch']), int(r['pid']), float(r['cpu_s']), int(r['rss_anon_bytes']), int(r['swap_bytes']))
          for r in rows(os.path.join(d, f'procinfo_{name}.csv.gz'))]
    hs = sorted(blk); stalls = []
    for x, y in zip(hs, hs[1:]):
        if blk[y] - blk[x] >= STALL_GAP:
            before = [q for t, q, *_ in pi if t <= blk[x]]; after = [q for t, q, *_ in pi if t >= blk[y]]
            if before and after and before[-1] != after[0]: stalls.append((x, blk[y] - blk[x]))
    def caught(h):
        xs = [x for x in range(h, h + 200, 10) if x in blk and x in stamp]
        return len(xs) >= 10 and all(blk[x] - stamp[x] < LAG for x in xs)
    lo, hi = hs[0], hs[-1] - 200
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if caught(mid): hi = mid
        else: lo = mid
    R[name] = dict(start=start, blk=blk, pi=pi, stalls=stalls, catch=hi)
    print(f"{name}: blocks {hs[0]}..{hs[-1]}; caught up at {hi}; stalls: " +
          (', '.join(f"{fmt(g)} after block {x}" for x, g in stalls) or 'none'))
H = min(r['catch'] for r in R.values())
print(f"\ncommon range: block {START_HEIGHT + 1} to {H} (the earliest catch-up)")
print("| run | total | stalls | without stalls | peak RssAnon | peak swap | peak RssAnon+swap |")
print("|---|---|---|---|---|---|---|")
base = None
for name, _ in runs:
    r = R[name]; gross = r['blk'][H] - r['start']; st = sum(g for x, g in r['stalls'] if x < H); net = gross - st
    w = [p for p in r['pi'] if r['start'] <= p[0] <= r['blk'][H]]
    ra = max(p[3] for p in w) / MIB; sw = max(p[4] for p in w) / MIB; su = max(p[3] + p[4] for p in w) / MIB
    rel = '' if base is None else f" ({100 * (gross / base[0] - 1):+.1f}% total, {100 * (net / base[1] - 1):+.1f}% without stalls)"
    print(f"| {name} | {fmt(gross)} | {fmt(st) if st else 'none'} | {fmt(net)}{rel} | {ra:,.0f} MiB | {sw:,.0f} MiB | {su:,.0f} MiB |")
    if base is None: base = (gross, net)
